create table disponibilidade (hora_fim time(0), hora_inicio time(0), fk_voluntario bigint not null, nro_disp bigint generated by default as identity, dia_semana enum ('DOMINGO','QUARTA','QUINTA','SABADO','SEGUNDA','SEXTA','TERCA'), primary key (nro_disp));
create table habilidade (habilidade_id bigint generated by default as identity, nome varchar(255), primary key (habilidade_id));
create table instituicao (fk_usuario bigint not null, cnpj varchar(255), estatuto_social varchar(255), primary key (fk_usuario));
create table match_requisicao (data_criacao timestamp(6) with time zone not null, fk_disponibilidade bigint not null, fk_requisicao_habilidade bigint not null, match_requisicao_id bigint generated by default as identity, status enum ('CONFIRMADO','PENDENTE','RECUSADO') not null, primary key (match_requisicao_id));
create table requisicao_habilidade (qtd_habilidade integer not null, fk_habilidade bigint not null, fk_tarefa bigint not null, requisicao_habilidade_id bigint generated by default as identity, primary key (requisicao_habilidade_id), constraint uk_tarefa_habilidade unique (fk_tarefa, fk_habilidade));
create table tarefa (data date not null, hora_fim time(0) not null, hora_inicio time(0) not null, fk_instituicao bigint not null, tarefa_id bigint generated by default as identity, bairro varchar(255) not null, cep varchar(255) not null, cidade varchar(255) not null, descricao varchar(255) not null, estado varchar(255) not null, nome varchar(255) not null, rua varchar(255) not null, dia_semana enum ('DOMINGO','QUARTA','QUINTA','SABADO','SEGUNDA','SEXTA','TERCA') not null, status enum ('ABERTA','CANCELADA','CONCLUIDA','EM_ANDAMENTO') not null, primary key (tarefa_id));
create table usuario (usuario_id bigint generated by default as identity, tipo varchar(31) not null check ((tipo in ('INST','VOL'))), bairro varchar(255), cep varchar(255), cidade varchar(255), email varchar(255), estado varchar(255), login varchar(255), nome varchar(255), numero varchar(255), rua varchar(255), senha varchar(255), telefone varchar(255), primary key (usuario_id));
create table voluntario (fk_usuario bigint not null, cpf varchar(255), primary key (fk_usuario));
create table voluntario_habilidade (fk_habilidade bigint not null, fk_voluntario bigint not null, primary key (fk_habilidade, fk_voluntario));
alter table if exists disponibilidade add constraint FKt8i4yqqhwfmciefsf886hbc80 foreign key (fk_voluntario) references voluntario;
alter table if exists instituicao add constraint FKgjd6h6abcichylxx8vfdv0xxj foreign key (fk_usuario) references usuario;
alter table if exists match_requisicao add constraint FK6fu68brin0124pi20ujk3vccr foreign key (fk_disponibilidade) references disponibilidade;
alter table if exists match_requisicao add constraint FKgpbmj7rbrtsubj6ihim7o1eya foreign key (fk_requisicao_habilidade) references requisicao_habilidade;
alter table if exists requisicao_habilidade add constraint FKhq43qrn3gw2swty3bmbkjilpe foreign key (fk_habilidade) references habilidade;
alter table if exists requisicao_habilidade add constraint FK7t5ue3nmbs62ef2t8vh4w4inm foreign key (fk_tarefa) references tarefa;
alter table if exists tarefa add constraint FKmmy4cmdq1eu7xiwmlxkifx4kv foreign key (fk_instituicao) references instituicao;
alter table if exists voluntario add constraint FKgh9j4hkgwftqji99w3p18b664 foreign key (fk_usuario) references usuario;
alter table if exists voluntario_habilidade add constraint FKlkb4o0r1bq0l6hqce2k2mlpya foreign key (fk_habilidade) references habilidade;
alter table if exists voluntario_habilidade add constraint FK5c4icas6s0qk4v81qwllw6ovh foreign key (fk_voluntario) references voluntario;
